static INDEX: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();

pub fn all() -> &'static [Cmd] {
    COMMANDS
}

pub fn find(id: &str) -> Option<&'static Cmd> {
    let idx = INDEX.get_or_init(|| COMMANDS.iter().enumerate().map(|(i, c)| (c.id, i)).collect());
    idx.get(id).map(|i| &COMMANDS[*i])
}

pub fn menu_path(c: &Cmd) -> Vec<&'static str> {
    if c.menu.is_empty() { vec![] } else { c.menu.split('/').collect() }
}

pub fn schema(c: &Cmd) -> Json {
    let body = c.params.trim().trim_start_matches('{');
    let body = body.rsplit_once('}').map(|(a, _)| a).unwrap_or(body);
    let mut parts = vec![];
    let mut depth = 0i32;
    let mut cur = String::new();
    for ch in body.chars() {
        match ch {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            _ => {}
        }
        if ch == ',' && depth == 0 {
            parts.push(std::mem::take(&mut cur));
        } else {
            cur.push(ch);
        }
    }
    if !cur.trim().is_empty() {
        parts.push(cur);
    }
    let mut props = serde_json::Map::new();
    let mut required = vec![];
    for raw in parts {
        let p = raw.trim();
        let name: String = p.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
        if name.is_empty() {
            continue;
        }
        let rest = &p[name.len()..];
        let optional = rest.starts_with('?') || rest.trim_start().starts_with('|');
        let desc = rest.trim_start_matches('?').trim_start_matches(':').trim();
        props.insert(name.clone(), json!({"description": if desc.is_empty() { name.clone() } else { desc.to_string() }}));
        if !optional && name != "merge" {
            required.push(name);
        }
    }
    json!({"type": "object", "properties": props, "required": required, "description": c.params})
}
